  [`GET ${v}/companies/{companyId}/accounts`]: { tag: 'Ledger', summary: 'Chart of accounts', query: C.accountListQuerySchema, ok: [200, 'AccountList', 'Accounts'] },
  [`POST ${v}/companies/{companyId}/accounts`]: { tag: 'Ledger', summary: 'Create an account (code unique per company; subtype and reporting line must fit the type)', body: ['CreateAccountRequest', C.createAccountSchema], ok: [201, 'AccountView', 'Created'], extraErrors: [409] },
