  [`POST ${v}/companies/{companyId}/journals`]: { tag: 'Ledger', summary: 'Post a manual journal through the PostingService (balanced, open period, active non-control accounts; immutable once posted). Opening balances and control adjustments use journal requests', description: 'Foreign currency (M3): give `currency` other than the company\'s with line amounts in that currency; the server converts at a stored rate (`rateId`), a manual rate (`manualRate`, stored and audited) or the looked-up rate (transaction date, else the latest earlier daily rate within 7 days, else 422 `exchange_rate_not_found`). Each line is rounded per line, half-up, to the company currency; a visible FX-rounding line absorbs up to one minor unit per line. Opening balances and control adjustments are posted in the company currency only.', body: ['PostJournalRequest', C.postJournalSchema], ok: [201, 'JournalDetail', 'Posted'], extraErrors: [409] },
  [`GET ${v}/companies/{companyId}/journals`]: { tag: 'Ledger', summary: 'Journals, newest first', query: C.journalListQuerySchema, ok: [200, 'JournalPage', 'Journals'] },
  [`GET ${v}/companies/{companyId}/journals/{journalId}`]: { tag: 'Ledger', summary: 'A journal with its lines, source and reversal links', ok: [200, 'JournalDetail', 'Journal'] },
  [`POST ${v}/companies/{companyId}/journals/{journalId}/reverse`]: { tag: 'Ledger', summary: 'Reverse a journal with a linked mirror journal (once; a reversal cannot be reversed)', body: ['ReverseJournalRequest', C.reverseJournalSchema], ok: [201, 'JournalDetail', 'Reversed'], extraErrors: [409] },
  [`POST ${v}/companies/{companyId}/opening-balance-requests`]: { tag: 'Ledger', summary: 'Request an opening-balance journal (ledger:opening-balance). Validated like a journal but not posted: a pending request is not a ledger entry. Posted after approval by a different person, or at once when the company policy exempts it', body: ['CreateJournalRequest', C.createJournalRequestSchema], ok: [201, 'JournalRequest', 'Request created (or posted, when exempt)'], extraErrors: [422] },
  [`POST ${v}/companies/{companyId}/control-adjustment-requests`]: { tag: 'Ledger', summary: 'Request an exceptional adjustment of a control account (ledger:control-adjustment): reason and evidence required; approval per policy', body: ['CreateJournalRequest', C.createJournalRequestSchema], ok: [201, 'JournalRequest', 'Request created (or posted, when exempt)'], extraErrors: [422] },
  [`GET ${v}/companies/{companyId}/journal-requests`]: { tag: 'Ledger', summary: 'Journal requests, newest first (filter by status and kind)', query: C.requestListQuerySchema, ok: [200, 'JournalRequestPage', 'Requests'] },
  [`GET ${v}/companies/{companyId}/journal-requests/{requestId}`]: { tag: 'Ledger', summary: 'One journal request with its policy snapshot and outcome', ok: [200, 'JournalRequest', 'Request'] },
  [`POST ${v}/companies/{companyId}/journal-requests/{requestId}/approve`]: { tag: 'Ledger', summary: 'Approve a pending request (ledger:approve, never your own) - the PostingService posts the journal in the same transaction', body: ['DecideJournalRequest', C.decideRequestSchema], ok: [200, 'JournalRequest', 'Approved and posted'], extraErrors: [409, 422] },
