  [`POST ${v}/companies/{companyId}/journal-requests/{requestId}/cancel`]: { tag: 'Ledger', summary: 'The requester withdraws their own pending request', body: ['DecideJournalRequest', C.decideRequestSchema], ok: [200, 'JournalRequest', 'Cancelled'], extraErrors: [409] },
