  [`PUT ${v}/companies/{companyId}/ledger-policy`]: { tag: 'Ledger', summary: 'Set the approval policy (ledger:policy, reason required, audited with before/after). There is no mode that skips permission, reason, evidence or audit', body: ['SetLedgerPolicyRequest', C.setLedgerPolicySchema], ok: [200, 'LedgerPolicy', 'Policy set'], extraErrors: [422] },
  [`GET ${v}/companies/{companyId}/exchange-rates`]: { tag: 'Ledger', summary: 'Exchange rates of the organisation (current ones unless includeSuperseded)', query: C.rateListQuerySchema, ok: [200, 'ExchangeRatePage', 'Rates'] },
