  [`GET ${v}/companies/{companyId}/revaluation-runs`]: { tag: 'Ledger', summary: 'Revaluation runs, newest first', query: C.revaluationRunListQuerySchema, ok: [200, 'RevaluationRunPage', 'Runs'] },
